contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint fundAmount, uint withdrawValue) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= fundAmount, "insufficient test balance");

        // Fund c with a positive balance so the pre-call balance is meaningful.
        uint fundC = fundAmount + 1;

        uint cBalBefore = address(c).balance;
        uint callerBefore = address(this).balance;
        address ownerBefore = c.owner(); if (__ESBMC_reverted()) return;
        uint depositsBefore = c.depositsCount(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.withdraw(withdrawValue); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint cBalAfter = address(c).balance;
        uint callerAfter = address(this).balance;
        address ownerAfter = c.owner(); if (__ESBMC_reverted()) return;
        uint depositsAfter = c.depositsCount(); if (__ESBMC_reverted()) return;

        assert(
            (reverted == (withdrawValue > cBalBefore)) &&
            (reverted
                ? (cBalAfter == cBalBefore && callerAfter == callerBefore)
                : (cBalAfter == cBalBefore - withdrawValue &&
                   callerAfter == callerBefore + withdrawValue)) &&
            ownerAfter == ownerBefore &&
            depositsAfter == depositsBefore
        );
    }

    receive() external payable {}
}

